#!/usr/bin/env bash\n# Build script for Q+ LED Control\nset -e\n\necho \"================================================\"\necho \"Q+ LED Control - Build Script\"\necho \"================================================\"\necho \"\"\necho \"Target Device: Sunvell Q+ (Allwinner H6)\"\necho \"Android Version: 9 (API 28)\"\necho \"App Version: 1.0.0\"\necho \"\"\n\nif [ ! -f \"gradlew\" ]; then\n    echo \"ERROR: gradlew not found. Make sure you're in the project root.\"\n    exit 1\nfi\n\necho \"Step 1: Validating environment...\"\ngrep -q 'minSdk = 28' app/build.gradle.kts && echo \"✓ Min SDK 28 verified\"\ngrep -q 'targetSdk = 34' app/build.gradle.kts && echo \"✓ Target SDK 34 verified\"\n\necho \"\"\necho \"Step 2: Cleaning previous builds...\"\n./gradlew clean\n\necho \"\"\necho \"Step 3: Building debug APK...\"\n./gradlew assembleDebug --stacktrace\n\necho \"\"\necho \"Step 4: Verifying APK...\"\nif [ -f \"app/build/outputs/apk/debug/app-debug.apk\" ]; then\n    APK_SIZE=$(ls -lh app/build/outputs/apk/debug/app-debug.apk | awk '{print $5}')\n    echo \"✓ Debug APK created successfully\"\n    echo \"✓ APK size: $APK_SIZE\"\n    echo \"\"\n    echo \"APK location:\"\n    echo \"  $(pwd)/app/build/outputs/apk/debug/app-debug.apk\"\n    echo \"\"\n    echo \"Install command:\"\n    echo \"  adb install app/build/outputs/apk/debug/app-debug.apk\"\nelse\n    echo \"ERROR: APK not found at expected location\"\n    exit 1\nfi\n\necho \"\"\necho \"Step 5: Running tests...\"\n./gradlew test --stacktrace || echo \"⚠ Some tests failed or were skipped\"\n\necho \"\"\necho \"================================================\"\necho \"✓ Build process completed\"\necho \"================================================\"\n"